/**
 * Hold'em practice (PLAN.md 2.6): rated call-or-fold problems, the other player all-in with every
 * hand face up, each answer proved by exact equity and pot-odds arithmetic (generated by
 * scripts/generate-holdem-spots.ts); and four drills generated on the spot, on the lesson runner:
 *
 * - which hand wins at the showdown, cards up (the evaluator decides);
 * - count the outs to a straight or better (reading.ts, as the coach counts them);
 * - pot odds: the price of a call against an all-in, then call or fold with the equity shown
 *   (proved the same way as the problems);
 * - raise or fold first in, by the opening chart in preflop.ts (the bots' and the coach's).
 */
import type { Lesson } from '../../../teach/lesson';
import type { Problem } from '../../../teach/problem';
import type { DrillDef, PracticePack } from '../../practice';
import type { Card } from '../cards';
import { cardIndex, DECK, handClass } from '../cards';
import { categoryOf, evaluate } from '../evaluate';
import { inTop, openFraction, rankOf } from '../preflop';
import { outs, readHand } from '../reading';
import { holdem } from '../rules';
import { lessonPosition, pokerLessonGame } from '../learn/game';
import { holeOf } from '../learn/math';
import { MARGIN, prove } from '../learn/verify';
import type { Deal } from './spot';
import { allInSpot, LINES } from './spot';

interface SpotFile {
  readonly problems: readonly { id: string; position: string; setup: string; line: string[]; rating: number; themes: string[] }[];
}

/** You open on the button, the big blind calls; then the big blind checks each round to the river. */
const BTN_VS_BB = ['fold', 'fold', 'fold', 'r5', 'fold', 'call'];

function shuffle<T>(random: () => number, list: readonly T[]): T[] {
  const out = [...list];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

const pick = <T>(random: () => number, list: readonly T[]): T => list[Math.floor(random() * list.length)] as T;

function lesson(id: string, title: string, start: string, steps: Lesson['steps']): Lesson {
  return { id: `poker.drill.${id}`, gameId: 'poker', stage: 'table', title, minutes: 1, start, steps };
}

const holes = (you: readonly Card[], carmen: readonly Card[] | null): (Card[] | null)[] => [[...you], null, carmen ? [...carmen] : null, null, null, null];

/** Which hand wins: two hands face up on a finished board, chosen so many are close. */
function winnerDrill(random: () => number): Lesson {
  const want = pick(random, ['same-kind', 'same-kind', 'split', 'different', 'any'] as const);
  for (let tries = 0; ; tries++) {
    const deck = shuffle(random, DECK);
    const you = deck.slice(0, 2);
    const them = deck.slice(2, 4);
    const board = deck.slice(4, 9);
    const a = evaluate([...you, ...board]);
    const b = evaluate([...them, ...board]);
    const fits =
      want === 'same-kind' ? a !== b && categoryOf(a) === categoryOf(b) && categoryOf(a) !== 'high-card' : want === 'split' ? a === b : want === 'different' ? categoryOf(a) !== categoryOf(b) && Math.min(a, b) >> 20 >= 1 : true;
    if (!fits && tries < 400) continue;
    const start = lessonPosition({ button: 0, holes: holes(you, them), board, actions: [...BTN_VS_BB, 'check', 'check', 'check', 'check', 'check'] });
    const both = 'you have {hand}, {name:2} has {hand:2}.';
    const options = [
      { text: 'You', correct: a > b, why: a > b ? `Yes: ${both}` : `No: ${both}` },
      { text: '{name:2}', correct: b > a, why: b > a ? `Yes: ${both}` : `No: ${both}` },
      { text: 'A split pot', correct: a === b, why: a === b ? `Yes: the best five cards are equal; ${both}` : `No: ${both}` },
    ];
    return lesson('winner', 'Which hand wins', start, [{ kind: 'askChoice', openHand: true, text: 'Cards up, and the river is out. Who wins at the showdown?', options }]);
  }
}

/** Draws by how many outs they have, so the drill does not deal gutshot after gutshot. */
const OUT_BANDS: readonly (readonly [number, number])[] = [
  [4, 5],
  [6, 8],
  [9, 9],
  [10, 15],
];

/** Count the outs to a straight or better, on the flop or the turn. */
function outsDrill(random: () => number): Lesson {
  const [lo, hi] = pick(random, OUT_BANDS);
  for (let tries = 0; ; tries++) {
    const turn = random() < 0.4;
    const deck = shuffle(random, DECK);
    const you = deck.slice(0, 2);
    const board = deck.slice(2, 7);
    const shown = board.slice(0, turn ? 4 : 3);
    const draw = outs(you, shown).draw.length;
    const made = readHand(holeOf({ hole: you }), shown.map(cardIndex)).category;
    const madeAlready = made === 'straight' || made === 'flush' || made === 'full-house' || made === 'quads' || made === 'straight-flush';
    const wanted = tries < 3000 ? draw >= lo && draw <= hi : draw >= 4 && draw <= 15;
    if ((madeAlready || !wanted) && tries < 6000) continue;
    const start = lessonPosition({ button: 0, holes: holes(you, null), board, actions: [...BTN_VS_BB, 'check', ...(turn ? ['check', 'check'] : [])] });
    return lesson('outs', 'Count the outs', start, [
      { kind: 'askNumber', text: 'How many of the cards you cannot see would give you a straight or better?', answer: 'outs', success: 'Yes, {outs}. With {to-come} to come, the quick rule says about {rough}%; exactly, {hit}%.' },
    ]);
  }
}

/** The price of calling an all-in, then call or fold with every hand face up and the equity shown. */
function oddsDrill(random: () => number): Lesson {
  // Calls and folds about equally often.
  const want = random() < 0.5 ? 'call' : 'fold';
  for (let tries = 0; ; tries++) {
    const street = random() < 0.55 ? 'flop' : 'turn';
    const deck = shuffle(random, DECK);
    const deal: Deal = { you: deck.slice(0, 2), them: deck.slice(2, 4), board: deck.slice(4, 9) };
    const shown = deal.board.slice(0, street === 'flop' ? 3 : 4).map(cardIndex);
    if (readHand(holeOf({ hole: deal.them }), shown).tier < 2) continue;
    const mine = readHand(holeOf({ hole: deal.you }), shown);
    if (mine.tier < 1 && mine.draws.length === 0) continue;
    const spot = allInSpot(pick(random, LINES), street, deal, pick(random, [0.33, 0.5, 0.67, 0.75, 1, 1.5, 2]));
    if (!spot) continue;
    const facing = holdem.apply(spot.before, holdem.codec.action.fromText(spot.setup)).state;
    const proof = prove(facing, true);
    if (proof.kind !== 'call' || Math.abs(proof.gain) < MARGIN * proof.stake) continue;
    // Within reach of the price either way, so the arithmetic matters.
    const need = proof.stake > 0 ? (proof.stake - potBefore(facing)) / proof.stake : 0;
    if (Math.abs(proof.equity - need) > 0.2 || (proof.best !== want && tries < 2000)) continue;
    const call = proof.best === 'call';
    const name = `{name:${spot.before.toAct ?? 2}}`;
    return lesson('odds', 'Pot odds', holdem.codec.state.toText(facing), [
      { kind: 'askNumber', text: `${name} moves all-in: {call} more to call into a pot of {pot}. What share of the final pot is your call, to the nearest per cent?`, answer: 'need', success: 'Yes, {need}%: you put in {call} of the {final} you could win.' },
      {
        kind: 'askMove',
        openHand: true,
        text: `Cards up: against ${name}’s hand your equity is {equity}%. Call or fold?`,
        accept: [proof.best],
        wrong: call ? { fold: 'Your {equity}% is more than the {need}% the price asks. Call.' } : { call: 'Your {equity}% is less than the {need}% the price asks. Fold.' },
        claim: 'best',
        success: call ? 'Call: {equity}% beats the {need}% you need.' : 'Fold: {equity}% is short of the {need}% you need.',
      },
    ]);
  }
}

/** The pot before the call: everything in the middle. */
const potBefore = (s: ReturnType<typeof holdem.codec.state.fromText>): number => s.players.reduce((a, p) => a + p.total, 0);

const SEATS = [
  { pos: 'UTG', button: 3, folds: 0 },
  { pos: 'HJ', button: 2, folds: 1 },
  { pos: 'CO', button: 1, folds: 2 },
  { pos: 'BTN', button: 0, folds: 3 },
  { pos: 'SB', button: 5, folds: 4 },
] as const;

/** Raise or fold first in, by the opening chart: often a hand near the edge of the range. */
function preflopDrill(random: () => number): Lesson {
  const seat = pick(random, SEATS);
  const fraction = openFraction(seat.pos, 6);
  const edge = random() < 0.6;
  let hole: Card[] = [];
  for (let tries = 0; tries < 400; tries++) {
    hole = shuffle(random, DECK).slice(0, 2);
    const r = rankOf(handClass(hole[0] as Card, hole[1] as Card));
    if (!edge || Math.abs(r - fraction) < 0.08) break;
  }
  const cls = handClass(hole[0] as Card, hole[1] as Card);
  const start = lessonPosition({ button: seat.button, holes: holes(hole, null), actions: Array.from({ length: seat.folds }, () => 'fold') });
  const raise = inTop(cls, fraction);
  const state = pokerLessonGame.position(start);
  const bb = state.blinds.bb;
  const sizes = pokerLessonGame.moves(state).filter((m) => m.startsWith('r') && Number(m.slice(1)) >= 2 * bb && Number(m.slice(1)) <= 4 * bb);
  const limp = 'Raise or fold: just calling the big blind first in is not in the chart.';
  const wrong: Record<string, string> = { call: limp };
  if (raise) wrong.fold = 'This hand is in the chart for {pos}: the best {open}% of hands. Raise.';
  else for (const m of sizes) wrong[m] = 'This hand is outside the chart for {pos}: the best {open}% of hands. Fold.';
  return lesson('preflop', 'Raise or fold', start, [
    {
      kind: 'askMove',
      text: 'Nobody has raised, and you are {pos:at} with {class:words}. By the chart, raise or fold?',
      accept: raise ? sizes : ['fold'],
      wrong,
      claim: 'legal',
      success: raise ? 'Raise: from {pos} the chart opens the best {open}% of hands, and this one is in it.' : 'Fold: from {pos} the chart opens the best {open}% of hands, and this one is not in it.',
    },
  ]);
}

export const POKER_DRILLS: readonly DrillDef[] = [
  { id: 'drill-poker-winner', make: winnerDrill },
  { id: 'drill-poker-outs', make: outsDrill },
  { id: 'drill-poker-odds', make: oddsDrill },
  { id: 'drill-poker-preflop', make: preflopDrill },
];

export async function loadPokerPractice(): Promise<PracticePack> {
  const file = (await import('./spots.json')).default as unknown as SpotFile;
  const problems: Problem[] = file.problems.map((p) => ({ id: p.id, position: p.position, setup: p.setup, line: p.line, rating: p.rating, themes: p.themes, openHand: true }));
  return {
    problems,
    sets: [{ id: 'spots', themes: ['poker-all-in'], chips: ['poker-draw', 'poker-made-hand', 'poker-flop', 'poker-turn'] }],
    drills: POKER_DRILLS,
    attribution: null,
    game: pokerLessonGame,
    themeOrder: ['poker-combo-draw', 'poker-flush-draw', 'poker-straight-draw', 'poker-overcards', 'poker-made-hand', 'poker-draw', 'poker-flop', 'poker-turn', 'poker-all-in'],
  };
}
